import json
from collections import defaultdict

def transform_fill_gaps_diagonals(grid):
    """
    For each diagonal (constant r-c), fill ALL gaps between consecutive specials.
    Use the LATER cell's value when filling.
    ALL cells between two special cells (inclusive of gap only, not overwriting ends) get filled.
    """
    background = 4
    R, C = len(grid), len(grid[0])
    specials = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] != background:
                specials[(r, c)] = grid[r][c]
    result = [[grid[r][c] for c in range(C)] for r in range(R)]
    by_diag = defaultdict(list)
    for (r, c), val in specials.items():
        by_diag[r - c].append((r, c, val))
    for diag_id, cells in by_diag.items():
        cells_sorted = sorted(cells, key=lambda x: (x[0], x[1]))
        for i in range(len(cells_sorted) - 1):
            (r0, c0, val0) = cells_sorted[i]
            (r1, c1, val1) = cells_sorted[i + 1]
            # Fill ALL gap cells with LATER value
            for r, c in zip(range(r0 + 1, r1), range(c0 + 1, c1)):
                result[r][c] = val1
    return result

def transform_fill_entire_segments(grid):
    """
    Fill entire diagonal segments for each value group.
    For consecutive same-value cells, fill from first to last special with that value.
    """
    background = 4
    R, C = len(grid), len(grid[0])
    specials = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] != background:
                specials[(r, c)] = grid[r][c]
    result = [[grid[r][c] for c in range(C)] for r in range(R)]
    by_diag = defaultdict(list)
    for (r, c), val in specials.items():
        by_diag[r - c].append((r, c, val))
    for diag_id, cells in by_diag.items():
        cells_sorted = sorted(cells, key=lambda x: (x[0], x[1]))
        # Group consecutive same-value cells
        groups = []
        i = 0
        n = len(cells_sorted)
        while i < n:
            current_val = cells_sorted[i][2]
            group_cells = [cells_sorted[i]]
            i += 1
            while i < n and cells_sorted[i][2] == current_val:
                group_cells.append(cells_sorted[i])
                i += 1
            groups.append(group_cells)
        # Fill between groups with LATER group value
        for gi in range(len(groups) - 1):
            grp0 = groups[gi]
            grp1 = groups[gi + 1]
            (r0, c0) = grp0[-1]
            (r1, c1) = grp1[0]
            val = grp1[0][2]
            for r, c in zip(range(r0 + 1, r1), range(c0 + 1, c1)):
                result[r][c] = val
    return result

